insert into public.medical_articles(slug,title,summary,body_html,category,keywords,content_type,author_name,reviewer_doctor_id,status,source_links,published_at,reviewed_at,evidence_updated_at,next_review_at,featured,noindex,risk_level,review_level,ai_assisted,review_notes) values
('cbc-report-basics','خواندن برگه CBC؛ آشنایی با اصطلاحات','گلبول قرمز، گلبول سفید، هموگلوبین و پلاکت چه هستند و هنگام مرور برگه شمارش سلول‌های خون به چه چیزهایی توجه کنیم؟','<h2>CBC چه چیزی را اندازه می‌گیرد؟</h2><p>شمارش کامل سلول‌های خون، گروهی از اندازه‌گیری‌ها درباره تعداد و اندازه سلول‌های خون است. روی برگه معمولاً این اصطلاحات را می‌بینید:</p><ul><li><strong>RBC:</strong> گلبول‌های قرمز که اکسیژن را جابه‌جا می‌کنند.</li><li><strong>WBC:</strong> گلبول‌های سفید که بخشی از دستگاه ایمنی هستند.</li><li><strong>HGB یا Hb:</strong> هموگلوبین؛ پروتئین حمل‌کننده اکسیژن در گلبول قرمز.</li><li><strong>HCT:</strong> سهم حجمی گلبول‌های قرمز از خون.</li><li><strong>PLT:</strong> پلاکت‌ها که در لخته‌شدن خون نقش دارند.</li></ul><h2>چطور برگه را مرور کنیم؟</h2><p>نام آزمایش، عدد، واحد و محدوده مرجع همان آزمایشگاه را کنار هم بخوانید. علامت بالا یا پایین، به‌تنهایی تشخیص بیماری نیست. نتیجه باید در کنار علائم و سابقه شما بررسی شود.</p><h2>برای پیگیری چه نگه داریم؟</h2><p>تصویر کامل برگه و تاریخ آن را در پرونده ذخیره کنید. درباره موارد علامت‌دار از پزشک سؤال کنید و با یک عدد، درمان را تغییر ندهید.</p>','آزمایش و نتایج',array['CBC','شمارش سلول‌های خون','برگه آزمایش'],'guide','تحریریه دکتر من',null,'published','[{"title": "MedlinePlus؛ Complete Blood Count (CBC)", "url": "https://medlineplus.gov/lab-tests/complete-blood-count-cbc/"}]'::jsonb,'2026-10-13T00:00:00Z'::timestamptz,'2026-10-13T00:00:00Z'::timestamptz,'2026-10-13'::date,'2027-04-13'::date,true,false,'low','editorial',true,'محتوای آموزشی عمومی با کمک هوش مصنوعی و تطبیق منابع اولیه در ۲۰۲۶/۱۰/۱۳؛ بازبینی پزشکی فردی ادعا نمی‌شود.'),
('prepare-for-lab-test','پیش از آزمایش؛ چک‌لیست آماده‌شدن','دستور آزمایشگاه، ناشتا بودن و اطلاعات داروها را پیش از مراجعه بررسی کنید تا آمادگی شما با آزمایش درخواست‌شده هماهنگ باشد.','<h2>پیش از روز آزمایش</h2><p>همه آزمایش‌ها آمادگی یکسان ندارند. دستور پزشک یا آزمایشگاه را بخوانید و اگر مبهم است، پیش از مراجعه بپرسید:</p><ul><li>آیا برای همین آزمایش باید ناشتا باشم؟ اگر بله، دقیقاً چند ساعت؟</li><li>درباره مصرف آب، زمان نمونه‌گیری یا فعالیت بدنی چه دستور ویژه‌ای دارم؟</li><li>داروها، ویتامین‌ها و مکمل‌هایی که مصرف می‌کنم را چگونه اعلام کنم؟</li></ul><h2>دارو را خودسرانه قطع نکنید</h2><p>فهرست داروها و مکمل‌ها را به مسئول نمونه‌گیری یا پزشک بگویید. فقط اگر پزشک دستور داده است، مصرف دارو را برای آزمایش تغییر دهید. ناشتا بودن را نیز بدون درخواست مشخص، به همه آزمایش‌ها تعمیم ندهید.</p><h2>اگر دستور را کامل رعایت نکردم؟</h2><p>موضوع را پیش از نمونه‌گیری صادقانه اعلام کنید؛ ممکن است روی نتیجه اثر بگذارد. مسئول آزمایشگاه تصمیم می‌گیرد نمونه‌گیری انجام شود یا زمان دیگری مناسب‌تر باشد. برگه درخواست و اطلاعات لازم را همراه داشته باشید.</p>','آزمایش و نتایج',array['آمادگی آزمایش','ناشتا بودن','آزمایشگاه'],'guide','تحریریه دکتر من',null,'published','[{"title": "MedlinePlus؛ How to Prepare for a Lab Test", "url": "https://medlineplus.gov/lab-tests/how-to-prepare-for-a-lab-test/"}]'::jsonb,'2026-10-13T00:00:00Z'::timestamptz,'2026-10-13T00:00:00Z'::timestamptz,'2026-10-13'::date,'2027-04-13'::date,true,false,'low','editorial',true,'محتوای آموزشی عمومی با کمک هوش مصنوعی و تطبیق منابع اولیه در ۲۰۲۶/۱۰/۱۳؛ بازبینی پزشکی فردی ادعا نمی‌شود.'),
('mri-visit-checklist','قبل از ام‌آر‌آی چه چیزهایی بدانیم؟','آمادگی عمومی برای مراجعه به MRI: اعلام وسایل کاشته‌شده، هماهنگی با مرکز و دانستن اینکه گزارش و تصاویر چه کاربردی دارند.','<h2>ام‌آر‌آی چگونه تصویر می‌سازد؟</h2><p>MRI با میدان مغناطیسی و امواج رادیویی تصویر می‌سازد و از اشعه ایکس استفاده نمی‌کند. دستور آمادگی ممکن است با نوع بررسی و مرکز متفاوت باشد.</p><h2>پیش از مراجعه چه بگویم؟</h2><ul><li>وجود وسیله کاشته‌شده یا فلز در بدن، از جمله ضربان‌ساز یا ایمپلنت، را به مرکز اعلام کنید. کارت یا مشخصات وسیله را همراه ببرید.</li><li>احتمال بارداری، بیماری‌های مهم، جراحی اخیر و حساسیت‌های خود را اعلام کنید.</li><li>اگر فضای بسته برایتان اضطراب‌آور است، از قبل با مرکز هماهنگ کنید.</li></ul><h2>روز مراجعه</h2><p>درباره خوردن و آشامیدن از همان مرکز سؤال کنید. زیورآلات و وسایل فلزی یا الکترونیکی را مطابق راهنمای مسئول تصویربرداری کنار بگذارید. اعلام ایمپلنت، به‌تنهایی به معنی ممنوع‌بودن MRI نیست؛ بررسی سازگاری با مرکز است.</p><h2>بعد از تصویربرداری</h2><p>گزارش رادیولوژی و راه دسترسی به مجموعه تصاویر را دریافت کنید. تفسیر تصاویر تخصصی با رادیولوژیست است.</p>','تصویربرداری',array['MRI','ام‌آر‌آی','تصویربرداری'],'guide','تحریریه دکتر من',null,'published','[{"title": "RadiologyInfo؛ Body MRI (بازبینی منبع: ۱۵ ژوئن ۲۰۲۶)", "url": "https://www.radiologyinfo.org/en/info/bodymr"}]'::jsonb,'2026-10-13T00:00:00Z'::timestamptz,'2026-10-13T00:00:00Z'::timestamptz,'2026-10-13'::date,'2027-04-13'::date,true,false,'low','editorial',true,'محتوای آموزشی عمومی با کمک هوش مصنوعی و تطبیق منابع اولیه در ۲۰۲۶/۱۰/۱۳؛ بازبینی پزشکی فردی ادعا نمی‌شود.'),
('keep-medical-images','چطور گزارش و تصاویر پزشکی را در پرونده نگه داریم؟','اصل برگه آزمایش، گزارش رادیولوژی و تصاویر را کنار تفسیر نگه دارید تا پرونده سلامت شما برای پیگیری کامل‌تر باشد.','<h2>تفسیر را کنار اصل سند نگه دارید</h2><p>نتیجه آزمایش فقط بخشی از اطلاعات لازم برای ارزیابی سلامت است؛ سابقه، علائم و بررسی‌های دیگر نیز اهمیت دارند. نگه‌داشتن اصل سند کمک می‌کند پزشک جزئیات آن را مرور کند.</p><h2>چک‌لیست پرونده در دکتر من</h2><ol><li>پرونده عضو درست خانواده را انتخاب کنید.</li><li>تصویر خوانای برگه یا گزارش را با نوع سند مناسب و تاریخ بررسی ذخیره کنید.</li><li>عنوان روشنی مانند «MRI زانو، مهر ۱۴۰۵» بنویسید.</li><li>بعد از ذخیره، سند را باز کنید و کامل‌بودن صفحات و خوانایی را ببینید.</li></ol><h2>برای MRI چه نگه داریم؟</h2><p>گزارش نوشته‌شده و تصاویر مکمل هم‌اند. عکس چند نما، جای مجموعه اصلی تصویربرداری را نمی‌گیرد. فایل یا دیسک اصلی و روش دسترسی مرکز را نیز نگه دارید؛ پرونده آنلاین فعلاً تصاویر معمول و PDF را می‌پذیرد.</p><h2>اشتراک‌گذاری</h2><p>دسترسی پرونده را فقط برای پزشک موردنظر فعال کنید و پس از پایان نیاز، مجوز را بازبینی کنید.</p>','پرونده سلامت',array['پرونده سلامت','تصویر آزمایش','گزارش رادیولوژی'],'guide','تحریریه دکتر من',null,'published','[{"title": "MedlinePlus؛ How to Understand Your Lab Results", "url": "https://medlineplus.gov/lab-tests/how-to-understand-your-lab-results/"}, {"title": "RadiologyInfo؛ Body MRI", "url": "https://www.radiologyinfo.org/en/info/bodymr"}]'::jsonb,'2026-10-13T00:00:00Z'::timestamptz,'2026-10-13T00:00:00Z'::timestamptz,'2026-10-13'::date,'2027-04-13'::date,true,false,'low','editorial',true,'محتوای آموزشی عمومی با کمک هوش مصنوعی و تطبیق منابع اولیه در ۲۰۲۶/۱۰/۱۳؛ بازبینی پزشکی فردی ادعا نمی‌شود.')
